use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    // Arc's reference count is atomic, so the handle can be
    // cloned into another thread safely. Mutex gives the shared
    // interior mutability.
    let shared = Arc::new(Mutex::new(5));

    let mut handles = Vec::new();
    for _ in 0..8 {
        let shared = Arc::clone(&shared); // atomic increment
        handles.push(thread::spawn(move || {
            let mut guard = shared.lock().unwrap();
            *guard += 1;
            // guard drops here, releasing the mutex
        }));
    }

    for handle in handles {
        handle.join().unwrap();
    }

    println!("final value: {}", *shared.lock().unwrap()); // 13
}
